Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info,
                              MagickOffsetType PS_Offset, ssize_t PS_Size,
                              ExceptionInfo *exception)
{
  Image *new_image = (Image *) NULL;
  ImageInfo *clone_info = (ImageInfo *) CloneImageInfo(image_info);
  char filename[MagickPathExtent];
  FILE *file = (FILE *) NULL;
  ssize_t count;

  GetPathComponent(image->filename, Unique, filename, MagickPathExtent);
  file = fopen(filename, "wb");
  if (file == (FILE *) NULL)
    {
      ThrowFileException(exception, FileOpenError, filename, "PS image");
      goto cleanup;
    }

  if (WriteBlobFile(file, PS_Offset, PS_Size, (void *) NULL) != PS_Size)
    {
      fclose(file);
      (void) UnlinkBlobFile(filename);
      ThrowFileException(exception, WriteError, filename, "PS image");
      goto cleanup;
    }

  (void) fclose(file);
  file = fopen(filename, "rb");
  if (file == (FILE *) NULL)
    {
      (void) UnlinkBlobFile(filename);
      ThrowFileException(exception, FileOpenError, filename, "PS image");
      goto cleanup;
    }

  new_image = ReadImage(clone_info, file, exception);
  if (new_image == (Image *) NULL)
    {
      (void) fclose(file);
      (void) UnlinkBlobFile(filename);
      goto cleanup;
    }

  *image = *GetFirstImageInList(new_image);
  image->next = (Image *) NULL;
  DestroyImageList(new_image);

cleanup:
  if (file != (FILE *) NULL)
    (void) fclose(file);
  (void) UnlinkBlobFile(filename);
  clone_info = DestroyImageInfo(clone_info);

  return image;
}

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info,
                                MagickOffsetType PS_Offset, ssize_t PS_Size,
                                ExceptionInfo *exception) {
  Image *new_image = NULL;
  ImageInfo *clone_info = CloneImageInfo(image_info);
  char filename[MaxTextLength];
  FILE *file = NULL;
  size_t written;

  if (clone_info == (ImageInfo *) NULL) {
    ThrowImageException(ResourceLimitError, "MemoryAllocationFailed");
    return image;
  }

  (void) FormatLocaleString(filename, MaxTextLength, "%s/ps-%s.x", GetImageInfoOption(clone_info, "temporary"), GetImageInfoFilename(clone_info));
  file = fopen(filename, "wb");
  if (file == (FILE *) NULL) {
    clone_info = DestroyImageInfo(clone_info);
    ThrowImageException(FileOpenError, "UnableToCreateFile", filename);
    return image;
  }

  if (PS_Size > 0) {
    MagickBooleanType status = WriteBlob(image, PS_Size, image->pixels + PS_Offset, exception);
    if (!status) {
      fclose(file);
      clone_info = DestroyImageInfo(clone_info);
      return image;
    }
  }

  fclose(file);

  new_image = ReadImage(clone_info, exception);
  clone_info = DestroyImageInfo(clone_info);
  if (new_image == (Image *) NULL) {
    return image;
  }

  if (image->next != (Image *) NULL) {
    AppendImageToList(&new_image, image->next);
  }

  (void) CopyImageProperties(new_image, image);
  (void) CopyImageProfiles(new_image, image);

  return new_image;
}

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info, MagickOffsetType PS_Offset, ssize_t PS_Size, ExceptionInfo *exception)
{
  ImageInfo *clone_info;
  char filename[MaxTextLength];
  FILE *file;
  Image *new_image = NULL;

  clone_info = CloneImageInfo(image_info);
  GetPathComponent(image->filename,FileName,filename,filename);
  (void) AppendToPath(filename, "psXXXXXX");
  (void) mktemp(filename);
  file = fopen(filename, "wb");
  if (file == (FILE *) NULL)
  {
    ThrowFileException(exception, FileOpenError, filename, image->filename);
    return image;
  }

  if (WriteBlob(image, PS_Size, (void *) AcquireMemory((size_t) PS_Size), (void *) NULL) != MagickTrue)
  {
    (void) fclose(file);
    return image;
  }

  if (MagickSeekBlob(image, PS_Offset, SEEK_SET) != PS_Offset)
  {
    (void) fclose(file);
    return image;
  }

  if (WriteBlob(image, PS_Size, filename, (void *) NULL) != MagickTrue)
  {
    (void) fclose(file);
    return image;
  }

  (void) fclose(file);

  clone_info->filename = (char *) filename;
  new_image = ReadImage(clone_info, exception);
  if (new_image == (Image *) NULL)
  {
    (void) RemoveFile(filename);
    return image;
  }

  (void) RemoveFile(filename);
  if (image->next != (Image *) NULL)
    AppendImageFormat(new_image, image->next);

  (void) CloneImageAttributes(new_image, image);
  image = DestroyImage(image);
  return new_image;
}

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info,
                               MagickOffsetType PS_Offset, ssize_t PS_Size,
                               ExceptionInfo *exception) {
  Image
    *new_image;

  ImageInfo
    *clone_info;

  char
    filename[MaxTextLength];

  FILE
    *file;

  size_t
    length;

  ssize_t
    count;

  unsigned char
    *buffer;

  /*
   Clone the image info.
  */
  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL)
    return (Image *) image;
  GetPathComponent(image->filename,FileName,filename);
  (void) CopyMagickString(clone_info->filename,filename,MaxTextLength);
  (void) ConcatenateMagickString(clone_info->filename,".tmp",MaxTextLength);
  file = AllocateFileHandle();
  if (file == (FILE *) NULL)
    {
      (void) ThrowMagickException(exception,GetMagickModule(),FileOpenError,
        "Unable to open file","`%s'",filename);
      return (Image *) image;
    }
  if (MagickFileWritable(filename) != MagickTrue)
    {
      (void) fclose(file);
      (void) RelinquishUniqueFileResource(filename);
      (void) ThrowMagickException(exception,GetMagickModule(),FileOpenError,
        "Unable to open file","`%s'",filename);
      return (Image *) image;
    }
  (void) fseek(file,0,SEEK_SET);
  buffer = (unsigned char *) AcquireMemory(PS_Size);
  if (buffer == (unsigned char *) NULL)
    {
      (void) fclose(file);
      (void) RelinquishUniqueFileResource(filename);
      return (Image *) image;
    }
  length = PS_Size;
  count = ReadBlob(image,PS_Size,buffer);
  if (count != PS_Size)
    {
      (void) fclose(file);
      (void) RelinquishUniqueFileResource(filename);
      (void) ThrowMagickException(exception,GetMagickModule(),CorruptImageError,
        "Unable to read Postscript data","`%s'",image->filename);
      return (Image *) image;
    }
  (void) fwrite(buffer,sizeof(*buffer),length,file);
  (void) fclose(file);
  new_image = ReadImage(clone_info,exception);
  if (new_image == (Image *) NULL)
    {
      (void) RelinquishUniqueFileResource(filename);
      return (Image *) image;
    }
  (void) RelinquishUniqueFileResource(filename);
  DestroyImageList(image);
  image = new_image;
  return image;
}

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info, MagickOffsetType PS_Offset, ssize_t PS_Size, ExceptionInfo *exception) {
    ImageInfo *clone_info = CloneImageInfo(image_info);
    char filename[MagickPathExtent];
    GetPathComponent(image->filename, TailPath, filename, MagickPathExtent);
    (void) CopyMagickString(clone_info->filename, filename, MagickPathExtent);

    GetPathComponent(clone_info->filename, UniquePath, filename, MagickPathExtent);
    clone_info->filename[MagickPathExtent - 1] = '\0';

    FILE *file = fopen(filename, "wb");
    if (!file) {
        ThrowFileException(exception, FileOpenError, CannotOpenFile, filename);
        return image;
    }

    if (WriteBlob(image, PS_Size, image->pixels + PS_Offset) != PS_Size) {
        fclose(file);
        (void) RelinquishUniqueFileResource(filename);
        return image;
    }

    fclose(file);

    image = ReadImage(clone_info, exception);
    if (!image) {
        (void) RelinquishUniqueFileResource(filename);
        return image;
    }

    (void) RelinquishUniqueFileResource(filename);
    return image;
}
